@php($sku=$product->skus->first())<div class="row g-5"><div class="col-md-6">@if($sku?->image_url)<img src="{{Storage::url($sku->image_url)}}" class="img-fluid rounded bg-white">@else<div class="bg-light rounded d-flex align-items-center justify-content-center" style="height:500px">No image</div>@endif</div><div class="col-md-6"><small>{{$product->category->name}} @if($product->brand) · {{$product->brand->name}} @endif</small><h1 class="mt-2">{{$product->name}}</h1><div class="fs-3 fw-bold">৳ {{number_format($sku?->price??0,2)}}</div><p class="mt-3">{{$product->description}}</p><p>Stock: {{$sku?->stock_quantity??0}}</p><div class="d-flex gap-2"><form method="POST" action="{{route('cart.add',$sku)}}">@csrf<input type="hidden" name="quantity" value="1"><button class="btn btn-dark">Add to cart</button></form>@auth<form method="POST" action="{{route('wishlist.toggle',$product)}}">@csrf<button class="btn btn-outline-danger">♡ Wishlist</button></form>@endauth</div><hr class="my-4"><h5>Reviews ({{$product->reviews->count()}}) · ★ {{$product->average_rating}}</h5>@foreach($product->reviews as $r)<div class="border-bottom py-2"><strong>{{$r->user->name}}</strong> <span>★ {{$r->rating}}</span><p class="mb-0">{{$r->comment}}</p></div>@endforeach@auth@if(!$product->reviews->contains('user_id',auth()->id()))<form method="POST" action="{{route('reviews.store',$product)}}" class="mt-4">@csrf<div class="row g-2"><div class="col-3"><select name="rating" class="form-select">@for($i=5;$i>=1;$i--)<option>{{$i}}</option>@endfor</select></div><div class="col-9"><input name="comment" class="form-control" placeholder="Your review"></div></div><button class="btn btn-outline-dark mt-2">Submit review</button></form>@endif@endauth</div></div>@endsection
